CREATE POLICY "nuru_msg_select" ON public.nuru_messages FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.nuru_conversations c WHERE c.id = conversation_id AND (c.user_id = auth.uid() OR c.is_shared = true)) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "nuru_msg_insert" ON public.nuru_messages;
CREATE POLICY "nuru_msg_insert" ON public.nuru_messages FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.nuru_conversations c WHERE c.id = conversation_id AND c.user_id = auth.uid()));
