DROP POLICY IF EXISTS "Observers can update credentials" ON public.observer_biometric_credentials;
CREATE POLICY "Observers can update credentials" ON public.observer_biometric_credentials FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.election_observers o WHERE o.id = observer_id AND o.user_id = auth.uid()));
DROP POLICY IF EXISTS "Observers can view own credentials" ON public.observer_biometric_credentials;
CREATE POLICY "Observers can view own credentials" ON public.observer_biometric_credentials FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.election_observers o WHERE o.id = observer_id AND o.user_id = auth.uid()) OR public.has_role(auth.uid(),'admin'));

