CREATE POLICY "Authenticated users can upload nuru documents" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'nuru-documents' AND ((storage.foldername(name))[1] = auth.uid()::text OR ((storage.foldername(name))[1] = 'constitutions' AND (storage.foldername(name))[2] = auth.uid()::text)));

